42	/**
43	 * SQL Dialect JDBC API implementation
44	 */
45	public class JDBCSQLDialect extends BasicSQLDialect implements SQLDataTypeConverter {
46	
47	    private static final Log log = Log.getLog(JDBCSQLDialect.class);
48	
49	    private static final String[] LONG_TEXT_TYPES = {
50	        "longtext",
51	        "clob",
52	        "text",
53	        "string",
54	        "nclob"
55	    };
56	
57	    private final String name;
58	    private final String id;
59	    private String[][] identifierQuoteString = new String[][]{{SQLConstants.DEFAULT_IDENTIFIER_QUOTE, SQLConstants.DEFAULT_IDENTIFIER_QUOTE}};
60	    private SQLStateType sqlStateType;
61	    private String searchStringEscape;
62	    private String catalogSeparator = String.valueOf(SQLConstants.STRUCT_SEPARATOR);
63	    private boolean isCatalogAtStart;
64	    private int catalogUsage = SQLDialect.USAGE_ALL;
65	    protected int schemaUsage = SQLDialect.USAGE_ALL;
66	    protected String validCharacters = "";
67	    private boolean supportsUnquotedMixedCase;
68	    private boolean supportsQuotedMixedCase;
69	    @NotNull
70	    private DBPIdentifierCase unquotedIdentCase = getDefaultIdentifiersCase();
71	    @NotNull
72	    private DBPIdentifierCase quotedIdentCase = getDefaultIdentifiersCase();
73	    private boolean supportsSubqueries = false;
74	
75	    private transient boolean typesLoaded = false;
76	
77	    public JDBCSQLDialect(String name, String id) {
78	        this.name = name;
79	        this.id = id;
80	    }
81	
82	    public void initDriverSettings(JDBCSession session, JDBCDataSource dataSource, JDBCDatabaseMetaData metaData) {
83	        String singleQuoteStr;
84	        try {
85	            singleQuoteStr = metaData.getIdentifierQuoteString();
86	        } catch (Throwable e) {
87	            log.debug("Error getting identifierQuoteString: " + e.getMessage());
88	            singleQuoteStr = SQLConstants.DEFAULT_IDENTIFIER_QUOTE;
89	        }
90	        if (singleQuoteStr != null) {
91	            singleQuoteStr = singleQuoteStr.trim();
92	            if (singleQuoteStr.isEmpty()) {
93	                singleQuoteStr = null;
94	            }
95	        }
96	        if (singleQuoteStr == null) {
97	            identifierQuoteString = new String[0][];
98	        } else {
99	            identifierQuoteString = new String[][]{{singleQuoteStr, singleQuoteStr}};
100	        }
101	
102	        try {
103	            switch (metaData.getSQLStateType()) {
104	                case DatabaseMetaData.sqlStateXOpen:
105	                    this.sqlStateType = SQLStateType.XOPEN;
106	                    break;
107	                case DatabaseMetaData.sqlStateSQL99:
108	                    this.sqlStateType = SQLStateType.SQL99;
109	                    break;
110	                default:
111	                    this.sqlStateType = SQLStateType.UNKNOWN;
112	                    break;
113	            }
114	        } catch (Throwable e) {
115	            log.debug("Error getting sqlStateType: " + e.getMessage());
116	            this.sqlStateType = SQLStateType.UNKNOWN;
117	        }
118	
119	        try {
120	            supportsSubqueries = metaData.supportsCorrelatedSubqueries() ||
121	                metaData.supportsSubqueriesInComparisons() ||
122	                metaData.supportsSubqueriesInExists() ||
123	                metaData.supportsSubqueriesInIns() ||
124	                metaData.supportsSubqueriesInQuantifieds();
125	        } catch (Throwable e) {
126	            log.debug("Error getting supportsSubqueries: " + e.getMessage());
127	        }
128	
129	        try {
130	            this.supportsUnquotedMixedCase = metaData.supportsMixedCaseIdentifiers();
131	        } catch (Throwable e) {
132	            log.debug("Error getting supportsUnquotedMixedCase:" + e.getMessage());
133	            this.supportsUnquotedMixedCase = false;
134	        }
135	        try {
136	            this.supportsQuotedMixedCase = metaData.supportsMixedCaseQuotedIdentifiers();
137	        } catch (Throwable e) {
138	            log.debug("Error getting supportsQuotedMixedCase: " + e.getMessage());
139	            this.supportsQuotedMixedCase = false;
140	        }
141	        try {
142	            if (metaData.storesUpperCaseIdentifiers()) {
143	                this.unquotedIdentCase = DBPIdentifierCase.UPPER;
144	            } else if (metaData.storesLowerCaseIdentifiers()) {
145	                this.unquotedIdentCase = DBPIdentifierCase.LOWER;
146	            } else {
147	                this.unquotedIdentCase = DBPIdentifierCase.MIXED;
148	            }
149	        } catch (Throwable e) {
150	            log.debug("Error getting unquotedIdentCase:" + e.getMessage());
151	            this.unquotedIdentCase = DBPIdentifierCase.MIXED;
152	        }
153	        try {
154	            if (metaData.storesUpperCaseQuotedIdentifiers()) {
155	                this.quotedIdentCase = DBPIdentifierCase.UPPER;
156	            } else if (metaData.storesLowerCaseQuotedIdentifiers()) {
157	                this.quotedIdentCase = DBPIdentifierCase.LOWER;
158	            } else {
159	                this.quotedIdentCase = DBPIdentifierCase.MIXED;
160	            }
161	        } catch (Throwable e) {
162	            log.debug("Error getting quotedIdentCase:" + e.getMessage());
163	            this.quotedIdentCase = DBPIdentifierCase.MIXED;
164	        }
165	        try {
166	            this.searchStringEscape = metaData.getSearchStringEscape();
167	        } catch (Throwable e) {
168	            log.debug("Error getting searchStringEscape:" + e.getMessage());
169	        }
170	        if (this.searchStringEscape == null) {
171	            this.searchStringEscape = ""; //$NON-NLS-1$
172	        }
173	        try {
174	            this.catalogSeparator = metaData.getCatalogSeparator();
175	            if (CommonUtils.isEmpty(this.catalogSeparator)) {
176	                this.catalogSeparator = String.valueOf(SQLConstants.STRUCT_SEPARATOR);
177	            }
178	        } catch (Throwable e) {
179	            log.debug("Error getting catalogSeparator:" + e.getMessage());
180	            this.catalogSeparator = String.valueOf(SQLConstants.STRUCT_SEPARATOR);
181	        }
182	        try {
183	            catalogUsage =
184	                (metaData.supportsCatalogsInDataManipulation() ? SQLDialect.USAGE_DML : 0) |
185	                    (metaData.supportsCatalogsInTableDefinitions() ? SQLDialect.USAGE_DDL : 0) |
186	                    (metaData.supportsCatalogsInProcedureCalls() ? SQLDialect.USAGE_PROC : 0) |
187	                    (metaData.supportsCatalogsInIndexDefinitions() ? SQLDialect.USAGE_INDEX : 0) |
188	                    (metaData.supportsCatalogsInPrivilegeDefinitions() ? SQLDialect.USAGE_PRIV : 0);
189	        } catch (Throwable e) {
190	            log.debug("Error getting catalogUsage:" + e.getMessage());
191	            catalogUsage = SQLDialect.USAGE_NONE;
192	        }
193	        try {
194	            schemaUsage =
195	                (metaData.supportsSchemasInDataManipulation() ? SQLDialect.USAGE_DML : 0) |
196	                    (metaData.supportsSchemasInTableDefinitions() ? SQLDialect.USAGE_DDL : 0) |
197	                    (metaData.supportsSchemasInProcedureCalls() ? SQLDialect.USAGE_PROC : 0) |
198	                    (metaData.supportsSchemasInIndexDefinitions() ? SQLDialect.USAGE_INDEX : 0) |
199	                    (metaData.supportsSchemasInPrivilegeDefinitions() ? SQLDialect.USAGE_PRIV : 0);
200	        } catch (Throwable e) {
201	            log.debug("Error getting schemaUsage:" + e.getMessage());
202	            schemaUsage = SQLDialect.USAGE_DDL | SQLDialect.USAGE_DML;
203	        }
204	        try {
205	            validCharacters = metaData.getExtraNameCharacters();
206	            if (validCharacters == null) {
207	                validCharacters = "";
208	            } else {
209	                validCharacters = validCharacters.trim();
210	            }
211	        } catch (Throwable e) {
212	            log.debug("Error getting validCharacters:" + e.getMessage());
213	            validCharacters = ""; //$NON-NLS-1$
214	        }
215	
216	        try {
217	            this.isCatalogAtStart = metaData.isCatalogAtStart();
218	        } catch (Throwable e) {
219	            log.debug("Error getting isCatalogAtStart:" + e.getMessage());
220	            this.isCatalogAtStart = true;
221	        }
222	
223	        loadDriverKeywords(session, dataSource, metaData);
224	    }
225	
226	
227	    @NotNull
228	    protected DBPIdentifierCase getDefaultIdentifiersCase() {
229	        return DBPIdentifierCase.MIXED;
230	    }
231	
232	    @NotNull
233	    @Override
234	    public String getDialectName() {
235	        return name;
236	    }
