244	    @Nullable
245	    @Override
246	    public String[][] getIdentifierQuoteStrings() {
247	        return identifierQuoteString;
248	    }
249	
250	    protected void setIdentifierQuoteString(String[][] identifierQuoteString) {
251	        this.identifierQuoteString = identifierQuoteString;
252	    }
253	
254	    @NotNull
255	    @Override
256	    public String[] getExecuteKeywords() {
257	        return new String[0];
258	    }
259	
260	    @NotNull
261	    @Override
262	    public String getSearchStringEscape() {
263	        return searchStringEscape;
264	    }
265	
266	    @Override
267	    public int getCatalogUsage() {
268	        return catalogUsage;
269	    }
270	
271	    @Override
272	    public int getSchemaUsage() {
273	        return schemaUsage;
274	    }
275	
276	    @NotNull
277	    @Override
278	    public String getCatalogSeparator() {
279	        return catalogSeparator;
280	    }
281	
282	    @Override
283	    public char getStructSeparator() {
284	        return SQLConstants.STRUCT_SEPARATOR;
285	    }
286	
287	    @Override
288	    public boolean isCatalogAtStart() {
289	        return isCatalogAtStart;
290	    }
291	
292	    @NotNull
293	    @Override
294	    public SQLStateType getSQLStateType() {
295	        return sqlStateType;
296	    }
297	
298	    @Override
299	    public boolean validIdentifierPart(char c, boolean quoted) {
300	        // Some driver return extra characters which must be quoted. We can't know this here.
301	        return Character.isLetter(c) || Character.isDigit(c) || c == '_' || (quoted && validCharacters.indexOf(c) != -1);
302	    }
303	
304	    @Override
305	    public boolean supportsUnquotedMixedCase() {
306	        return supportsUnquotedMixedCase;
307	    }
308	
309	    public void setSupportsUnquotedMixedCase(boolean supportsUnquotedMixedCase) {
310	        this.supportsUnquotedMixedCase = supportsUnquotedMixedCase;
311	    }
312	
313	    @Override
314	    public boolean supportsQuotedMixedCase() {
315	        return supportsQuotedMixedCase;
316	    }
317	
318	    protected void setSupportsQuotedMixedCase(boolean supportsQuotedMixedCase) {
319	        this.supportsQuotedMixedCase = supportsQuotedMixedCase;
320	    }
321	
322	    @NotNull
323	    @Override
324	    public DBPIdentifierCase storesUnquotedCase() {
325	        return unquotedIdentCase;
326	    }
327	
328	    protected void setUnquotedIdentCase(@NotNull DBPIdentifierCase unquotedIdentCase) {
329	        this.unquotedIdentCase = unquotedIdentCase;
330	    }
331	
332	    @NotNull
333	    @Override
334	    public DBPIdentifierCase storesQuotedCase() {
335	        return quotedIdentCase;
336	    }
337	
338	    @Override
339	    public boolean supportsSubqueries() {
340	        return supportsSubqueries;
341	    }
342	
343	    public void setSupportsSubqueries(boolean supportsSubqueries) {
344	        this.supportsSubqueries = supportsSubqueries;
345	    }
346	
347	    public boolean supportsUpsertStatement() {
348	        return false;
349	    }
350	
351	    @NotNull
352	    @Override
353	    public Collection<String> getDataTypes(@Nullable DBPDataSource dataSource) {
354	        if (!typesLoaded && dataSource instanceof JDBCDataSource) {
355	            loadDataTypesFromDatabase((JDBCDataSource) dataSource);
356	            typesLoaded = true;
357	        }
358	        return super.getDataTypes(dataSource);
359	    }
360	
361	    protected void loadDataTypesFromDatabase(JDBCDataSource dataSource) {
362	        clearDataTypes();
363	
364	        Collection<? extends DBSDataType> supportedDataTypes = dataSource.getLocalDataTypes();
365	        List<String> dataTypes = new ArrayList<>();
366	        if (supportedDataTypes != null) {
367	            for (DBSDataType dataType : supportedDataTypes) {
368	                if (!dataType.getDataKind().isComplex()) {
369	                    dataTypes.add(dataType.getName().toUpperCase(Locale.ENGLISH));
370	                }
371	            }
372	        }
373	
374	        if (dataTypes.isEmpty() && needsDefaultDataTypes()) {
375	            // Add default types
376	            Collections.addAll(dataTypes, SQLConstants.DEFAULT_TYPES);
377	        }
378	        addDataTypes(dataTypes);
379	    }
380	
381	    private void loadDriverKeywords(JDBCSession session, JDBCDataSource dataSource, JDBCDatabaseMetaData metaData) {
382	        try {
383	            // Keywords
384	            Collection<String> sqlKeywords = makeStringList(metaData.getSQLKeywords());
385	            if (!CommonUtils.isEmpty(sqlKeywords)) {
386	                for (String keyword : sqlKeywords) {
387	                    addSQLKeyword(keyword.toUpperCase());
388	                }
389	            }
390	        } catch (SQLException e) {
391	            log.debug("Error reading SQL keywords: " + e.getMessage());
392	        }
393	        try {
394	            // Functions
395	            Set<String> allFunctions = new HashSet<>();
396	            loadFunctions(session, metaData, allFunctions);
397	            // Remove functions which clashes with keywords
398	            allFunctions.removeIf(s -> getKeywordType(s) == DBPKeywordType.KEYWORD);
399	            addFunctions(allFunctions);
400	        } catch (Throwable e) {
401	            log.debug("Error reading SQL functions: " + e.getMessage());
402	        }
403	    }
404	
405	    protected void loadFunctions(JDBCSession session, JDBCDatabaseMetaData metaData, Set<String> allFunctions) throws DBException, SQLException {
406	        allFunctions.addAll(makeStringList(metaData.getNumericFunctions()));
407	        allFunctions.addAll(makeStringList(metaData.getStringFunctions()));
408	        allFunctions.addAll(makeStringList(metaData.getSystemFunctions()));
409	        allFunctions.addAll(makeStringList(metaData.getTimeDateFunctions()));
410	    }
411	
412	    private static List<String> makeStringList(String source) {
413	        List<String> result = new ArrayList<>();
414	        if (source != null && source.length() > 0) {
415	            StringTokenizer st = new StringTokenizer(source, ";,"); //$NON-NLS-1$
416	            while (st.hasMoreTokens()) {
417	                result.add(st.nextToken().trim());
418	            }
419	        }
420	        return result;
421	    }
422	
423	    @Override
424	    public String convertExternalDataType(@NotNull SQLDialect sourceDialect, @NotNull DBSTypedObject sourceTypedObject, @Nullable DBPDataTypeProvider targetTypeProvider) {
425	        if (targetTypeProvider != null) {
426	            String typeName = sourceTypedObject.getTypeName();
427	            if (CommonUtils.isNotEmpty(typeName)) {
428	                String externalTypeName = typeName.toLowerCase(Locale.ENGLISH);
429	                if (SQLConstants.DATA_TYPE_VARCHAR.equals(externalTypeName)) {
430	                    long maxLength = sourceTypedObject.getMaxLength();
431	                    if (maxLength <= 0) {
432	                        // Some databases can not have varchar data type without modifiers.
433	                        // Like PostgreSQL where varchar without modifiers == text.
434	                        // But other databases are more strict in this case
435	                        // Let's use another text data type instead
436	                        for (String textType : LONG_TEXT_TYPES) {
437	                            DBSDataType textDataType = targetTypeProvider.getLocalDataType(textType);
438	                            if (textDataType != null) {
439	                                return textDataType.getName();
440	                            }
441	                        }
442	                    }
443	                }
444	            }
445	        }
446	        return null;
447	    }
448	}
